//! 🔺️ Original STL solid, facets, fixed vertices and ordinal indexes remain in paid receiving custody.
use super::{StlSnapshot,StlTriangle};
use semio_framework_os_kernel::sqlite_snapshot::{SqliteDatabase,SqliteTable,SqliteRow,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase,artifact::receiving::{Direction,Projection,Scalar,AuthoredTable,cell,text_cell,row,push_row,sort,ordinal,integer,identity_position,parent_range,validate_schema,check_database,settle}};
use semio_framework_value::{ValueError,ValueRefusalKind};
use store::NativeSnapshotBodyWallet;
use std::{cell::{Cell,RefCell},mem::size_of};
type Result<T>=std::result::Result<T,ValueError>;
type Port<'a,'b,'c>=semio_framework_os_kernel::sqlite_snapshot::artifact::receiving::Port<'a,'b,'c,NativeSnapshotBodyWallet>;
const SQL:&str=include_str!("../🗄️.sql");
const NAMES:[&str;3]=["stl_solid","stl_facet","stl_vertex"];
fn refusal(kind:ValueRefusalKind,message:&'static str)->ValueError{ValueError::literal(kind,message)}
fn invalid(message:&'static str)->ValueError{refusal(ValueRefusalKind::InvalidValue,message)}
fn definition(index:usize)->&'static str{SQL.split(';').filter(|s|!s.trim().is_empty()).nth(index).unwrap().trim()}
fn empty()->StlSnapshot{StlSnapshot{schema:String::new(),solid_name:String::new(),triangles:Vec::new()}}
fn table<'a>(database:&'a SqliteDatabase,name:&str)->Result<&'a SqliteTable>{database.tables.iter().find(|t|t.name.eq_ignore_ascii_case(name)).ok_or_else(||invalid("STL authored table is missing"))}
fn text(row:&SqliteRow,column:usize)->Result<&str>{match row.values.get(column){Some(SqliteValue::Text(value))=>Ok(value),_=>Err(invalid("STL literal text cell is invalid"))}}
fn numeric_class(value:f64)->&'static str{if value.is_nan(){"nan"}else if value==f64::INFINITY{"positiveInfinity"}else if value==f64::NEG_INFINITY{"negativeInfinity"}else{"finite"}}
fn coordinates(row:&SqliteRow,port:&mut Port<'_,'_,'_>)->Result<[f64;3]>{
 let mut values=[0.0;3];for axis in 0..3{port.work(2,size_of::<f64>())?;let value=f64::from_bits(integer(row,6+axis*2)?as u64);if text(row,7+axis*2)?!=numeric_class(value){return Err(invalid("STL IEEE class differs from its original word"))}let query=row.values.get(3+axis);let agrees=if value.is_nan(){matches!(query,Some(SqliteValue::Null))}else{match query{Some(SqliteValue::Real(query))=>*query==value,Some(SqliteValue::Integer(query))=>value>=i64::MIN as f64&&value< -(i64::MIN as f64)&&value.fract()==0.0&&value as i64==*query&&*query as f64==value,_=>false}};if !agrees{return Err(invalid("STL IEEE query differs from its original word"))}values[axis]=value;}Ok(values)
}
fn point(frame:&mut Projection,id:i64,parent:i64,position:i64,point:&[f64;3],port:&mut Port<'_,'_,'_>)->Result<()>{row(frame,id,12,port)?;cell(frame,Scalar::Integer(parent),port)?;cell(frame,Scalar::Integer(position),port)?;for value in point{cell(frame,if value.is_nan(){Scalar::Null}else{Scalar::Real(*value)},port)?}for value in point{cell(frame,Scalar::Integer(value.to_bits()as i64),port)?;text_cell(frame,numeric_class(*value),port)?;}Ok(())}
fn project(source:&StlSnapshot,frame:&mut Projection,port:&mut Port<'_,'_,'_>)->Result<()>{
 let facets=source.triangles.len();let vertices=facets.checked_mul(3).ok_or_else(||refusal(ValueRefusalKind::WorkLimit,"STL vertex census overflow"))?;let total=facets.checked_add(vertices).and_then(|n|n.checked_add(1)).ok_or_else(||refusal(ValueRefusalKind::WorkLimit,"STL entity census overflow"))?;port.control.check_rows(total)?;let limits=port.control.limits();let bytes=(0..3).map(|i|NAMES[i].len()+definition(i).len()).sum::<usize>();if limits.max_tables<3||limits.max_columns<12||bytes>limits.max_schema_bytes{return Err(refusal(ValueRefusalKind::OwnershipLimit,"STL authored schema exceeds original ceiling"))}
 port.vector(3,&mut frame.database.tables,1)?;for(index,count)in[1,facets,vertices].into_iter().enumerate(){port.work(2,size_of::<SqliteTable>())?;frame.database.tables.push(SqliteTable{name:String::new(),sql:String::new(),rows:Vec::new()});let table=&mut frame.database.tables[index];port.text(NAMES[index],&mut table.name,2)?;port.text(definition(index),&mut table.sql,2)?;port.vector(count,&mut table.rows,2)?;}
 row(frame,1,3,port)?;text_cell(frame,&source.schema,port)?;text_cell(frame,&source.solid_name,port)?;push_row(frame,0,port)?;
 for(position,triangle)in source.triangles.iter().enumerate(){let id=ordinal(position.checked_add(1).ok_or_else(||refusal(ValueRefusalKind::WorkLimit,"STL facet identity overflow"))?)?;point(frame,id,1,ordinal(position)?,&triangle.normal,port)?;push_row(frame,1,port)?;for(index,vertex)in triangle.vertices.iter().enumerate(){let vertex_id=position.checked_mul(3).and_then(|n|n.checked_add(index)).and_then(|n|n.checked_add(1)).ok_or_else(||refusal(ValueRefusalKind::WorkLimit,"STL vertex identity overflow"))?;point(frame,ordinal(vertex_id)?,id,ordinal(index)?,vertex,port)?;push_row(frame,2,port)?;}}
 port.control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,total,total)
}
#[derive(semio_framework_value::RetireOwned)]
struct Reconstruction{snapshot:StlSnapshot,facet_indices:Vec<usize>,facet_ids:Vec<usize>,vertex_indices:Vec<usize>,vertex_ids:Vec<usize>}
impl Reconstruction{fn new()->Self{Self{snapshot:empty(),facet_indices:Vec::new(),facet_ids:Vec::new(),vertex_indices:Vec::new(),vertex_ids:Vec::new()}}}
fn identities(rows:&[SqliteRow],indices:&mut Vec<usize>,ids:&mut Vec<usize>,port:&mut Port<'_,'_,'_>)->Result<()>{
 port.vector(rows.len(),indices,1)?;port.vector(rows.len(),ids,1)?;for(index,row)in rows.iter().enumerate(){port.work(1,0)?;if row.values.len()!=12||integer(row,0)?!=row.rowid{return Err(invalid("STL entity identity or width is invalid"))}port.work(1,2*size_of::<usize>())?;indices.push(index);ids.push(index);}sort(ids,port,|a,b|Ok(rows[a].rowid.cmp(&rows[b].rowid)))?;for pair in ids.windows(2){port.work(1,0)?;if rows[pair[0]].rowid==rows[pair[1]].rowid{return Err(invalid("STL entity identity is duplicated"))}}Ok(())
}
fn indexed<'d>(database:&'d SqliteDatabase,frame:&mut Reconstruction,port:&mut Port<'_,'_,'_>)->Result<(&'d SqliteRow,&'d [SqliteRow],&'d [SqliteRow])>{
 let authored=[0,1,2].map(|i|AuthoredTable{name:NAMES[i],declaration:definition(i),columns:if i==0{3}else{12}});validate_schema(database,&authored,port)?;check_database(database,port)?;let solids=&table(database,NAMES[0])?.rows;if solids.len()!=1{return Err(invalid("STL requires one solid row"))}let solid=&solids[0];if solid.values.len()!=3||integer(solid,0)?!=solid.rowid{return Err(invalid("STL solid identity or width is invalid"))}
 let facets=&table(database,NAMES[1])?.rows;let vertices=&table(database,NAMES[2])?.rows;identities(facets,&mut frame.facet_indices,&mut frame.facet_ids,port)?;identities(vertices,&mut frame.vertex_indices,&mut frame.vertex_ids,port)?;sort(&mut frame.facet_indices,port,|a,b|Ok(integer(&facets[a],2)?.cmp(&integer(&facets[b],2)?)))?;sort(&mut frame.vertex_indices,port,|a,b|Ok(integer(&vertices[a],1)?.cmp(&integer(&vertices[b],1)?).then(integer(&vertices[a],2)?.cmp(&integer(&vertices[b],2)?))))?;
 for vertex in vertices{port.work(1,0)?;if identity_position(facets,&frame.facet_ids,integer(vertex,1)?,port)?.is_none(){return Err(invalid("STL vertex has an unknown facet"))}}
 Ok((solid,facets,vertices))
}
fn reconstruct(database:&SqliteDatabase,frame:&mut Reconstruction,port:&mut Port<'_ ,'_ ,'_>)->Result<()>{
 let(solid,facets,vertices)=indexed(database,frame,port)?;let root=solid.rowid;
 let schema=text(solid,1)?;let name=text(solid,2)?;port.control.admit_reconstruction_bytes(schema.len())?;port.text(schema,&mut frame.snapshot.schema,1)?;port.control.admit_reconstruction_bytes(name.len())?;port.text(name,&mut frame.snapshot.solid_name,1)?;port.vector(facets.len(),&mut frame.snapshot.triangles,2)?;
 for(position,index)in frame.facet_indices.iter().copied().enumerate(){let facet=&facets[index];port.work(2,0)?;if integer(facet,1)?!=root||integer(facet,2)?!=ordinal(position)?{return Err(invalid("STL facet parent or contiguous ordinal is invalid"))}let range=parent_range(vertices,&frame.vertex_indices,facet.rowid,1,port)?;if range.len()!=3{return Err(invalid("STL facets must own exactly three vertices"))}let mut point_indices=[0;3];for(position,index)in frame.vertex_indices[range].iter().copied().enumerate(){port.work(2,size_of::<usize>())?;if integer(&vertices[index],2)?!=ordinal(position)?{return Err(invalid("STL vertex ordinals must be zero, one and two"))}point_indices[position]=index;}
  let normal=coordinates(facet,port)?;let points=[coordinates(&vertices[point_indices[0]],port)?,coordinates(&vertices[point_indices[1]],port)?,coordinates(&vertices[point_indices[2]],port)?];port.work(2,size_of::<StlTriangle>())?;frame.snapshot.triangles.push(StlTriangle{normal,vertices:points});
 }
 let total=facets.len().checked_add(vertices.len()).ok_or_else(||refusal(ValueRefusalKind::WorkLimit,"STL reconstructed entity census overflow"))?;port.control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,total,total)
}
struct Settlement<'a,'b>{control:RefCell<&'a mut SqliteSnapshotControl<'b>>,before:usize,remaining:usize,phase:SqliteSnapshotPhase,post_body:Cell<bool>,cause:RefCell<Option<ValueError>>}
impl<'a,'b>Settlement<'a,'b>{
 fn new(control:&'a mut SqliteSnapshotControl<'b>,before:usize,phase:SqliteSnapshotPhase)->Self{let remaining=control.allocation_remaining_bytes();Self{control:RefCell::new(control),before,remaining,phase,post_body:Cell::new(false),cause:RefCell::new(None)}}
 fn finish_body(&self,owned:usize)->Result<()>{settle(&mut self.control.borrow_mut(),self.remaining,self.before,owned)?;self.post_body.set(true);Ok(())}
 fn observe(&self,owned:usize,completed:usize,total:usize)->bool{if !self.post_body.get(){return true}let result={let mut control=self.control.borrow_mut();settle(&mut control,self.remaining,self.before,owned).and_then(|_|control.checkpoint(self.phase,completed,total))};match result{Ok(())=>true,Err(error)=>{*self.cause.borrow_mut()=Some(error);false}}}
 fn refused(&self,owned:usize,error:ValueError)->ValueError{match settle(&mut self.control.borrow_mut(),self.remaining,self.before,owned){Err(cause)=>cause,Ok(())=>self.cause.borrow_mut().take().unwrap_or(error)}}
}
pub(super)fn project_receiving(source:&StlSnapshot,control:&mut SqliteSnapshotControl<'_>,owner:&mut store::NativeSnapshotDecodeOwner<'_,'_>)->Result<SqliteDatabase>{
 let result=(||{owner.native().checkpoint()?;let before=owner.native().owned_bytes();let maximum=before.checked_add(control.allocation_remaining_bytes()).ok_or_else(||refusal(ValueRefusalKind::OwnershipLimit,"STL original SQL ceiling overflow"))?;let settlement=Settlement::new(control,before,SqliteSnapshotPhase::ProjectSnapshot);let mut observer=|event:semio_framework_value::native_decoding::NativeDecodeProgress|settlement.observe(event.owned_bytes,event.completed,event.total);let result=owner.scoped_native(maximum,&mut observer,|owner|owner.receive::<Projection,SqliteDatabase>(|slot,native,body|{
  let mut control=settlement.control.borrow_mut();let mut port=Port{control:&mut control,native:Direction::Decode(native),body};port.work(1,size_of::<Projection>())?;*slot=Some(Projection::new());let frame=slot.as_mut().unwrap();project(source,frame,&mut port)?;port.work(1,size_of::<SqliteDatabase>())?;let owned=port.owned();drop(port);drop(control);settlement.finish_body(owned)?;Ok(std::mem::replace(&mut frame.database,SqliteDatabase{tables:Vec::new()}))
 }));match result{Ok(value)=>Ok(value),Err(error)=>Err(settlement.refused(owner.native().owned_bytes(),error))}})();result.map_err(|error|error.with_retained_progress(owner.progress()))
}
pub(super)fn reconstruct_receiving(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,owner:&mut store::NativeSnapshotEncodeOwner<'_,'_>)->Result<StlSnapshot>{
 let result=(||{owner.native().checkpoint()?;let before=owner.native().owned_bytes();let maximum=before.checked_add(control.allocation_remaining_bytes()).ok_or_else(||refusal(ValueRefusalKind::OwnershipLimit,"STL original SQL ceiling overflow"))?;let settlement=Settlement::new(control,before,SqliteSnapshotPhase::ReconstructSnapshot);let mut observer=|event:semio_framework_value::native_encoding::NativeEncodeProgress|settlement.observe(event.owned_bytes,event.completed,event.total);let result=owner.scoped_native(maximum,&mut observer,|owner|owner.receive::<Reconstruction,StlSnapshot>(|slot,native,body|{
  let mut control=settlement.control.borrow_mut();let mut port=Port{control:&mut control,native:Direction::Encode(native),body};port.work(1,size_of::<Reconstruction>())?;*slot=Some(Reconstruction::new());let frame=slot.as_mut().unwrap();reconstruct(database,frame,&mut port)?;port.work(1,size_of::<StlSnapshot>())?;let owned=port.owned();drop(port);drop(control);settlement.finish_body(owned)?;Ok(std::mem::replace(&mut frame.snapshot,empty()))
 }));match result{Ok(value)=>Ok(value),Err(error)=>Err(settlement.refused(owner.native().owned_bytes(),error))}})();result.map_err(|error|error.with_retained_progress(owner.progress()))
}

fn equal_text(left:&str,right:&str,port:&mut Port<'_,'_,'_>)->Result<bool>{if left.len()!=right.len(){return Ok(false)}for(left,right)in left.as_bytes().chunks(256).zip(right.as_bytes().chunks(256)){port.work(1,0)?;if left!=right{return Ok(false)}}Ok(true)}
fn validate(source:&StlSnapshot,database:&SqliteDatabase,frame:&mut Reconstruction,port:&mut Port<'_,'_,'_>)->Result<()>{
 let(solid,facets,vertices)=indexed(database,frame,port)?;if !equal_text(&source.schema,text(solid,1)?,port)?||!equal_text(&source.solid_name,text(solid,2)?,port)?||facets.len()!=source.triangles.len(){return Err(invalid("STL document identity differs from its semantic projection"))}
 for(position,index)in frame.facet_indices.iter().copied().enumerate(){let facet=&facets[index];port.work(2,0)?;if integer(facet,1)?!=solid.rowid||integer(facet,2)?!=ordinal(position)?{return Err(invalid("STL facet parent or contiguous ordinal is invalid"))}let expected=&source.triangles[position];let normal=coordinates(facet,port)?;if normal.map(f64::to_bits)!=expected.normal.map(f64::to_bits){return Err(invalid("STL document identity differs from its semantic projection"))}let range=parent_range(vertices,&frame.vertex_indices,facet.rowid,1,port)?;if range.len()!=3{return Err(invalid("STL facets must own exactly three vertices"))}for(position,index)in frame.vertex_indices[range].iter().copied().enumerate(){let vertex=&vertices[index];port.work(2,0)?;if integer(vertex,2)?!=ordinal(position)?{return Err(invalid("STL vertex ordinals must be zero, one and two"))}let point=coordinates(vertex,port)?;if point.map(f64::to_bits)!=expected.vertices[position].map(f64::to_bits){return Err(invalid("STL document identity differs from its semantic projection"))}}
 }Ok(())
}
fn dialect(dialect:&semio_framework_artifact_reference::ArtifactDialect)->Result<()>{if dialect.artifact_kind!="s.stdio.stl"||dialect.standard!="ascii"||dialect.subset!="*"{return Err(invalid("geometry owned SQLite dialect differs"))}Ok(())}
pub(super)fn validate_decoding(source:&StlSnapshot,dialect_input:&semio_framework_artifact_reference::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,owner:&mut store::NativeSnapshotDecodeOwner<'_,'_>)->store::io_schema::IoResult<()>{
 let result=(||{owner.native().checkpoint()?;control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;dialect(dialect_input)?;let before=owner.native().owned_bytes();let maximum=before.checked_add(control.allocation_remaining_bytes()).ok_or_else(||refusal(ValueRefusalKind::OwnershipLimit,"STL original SQL ceiling overflow"))?;let settlement=Settlement::new(control,before,SqliteSnapshotPhase::ProjectSnapshot);let mut observer=|event:semio_framework_value::native_decoding::NativeDecodeProgress|settlement.observe(event.owned_bytes,event.completed,event.total);let result=owner.scoped_native(maximum,&mut observer,|owner|owner.receive::<Reconstruction,()>(|slot,native,body|{
  let mut control=settlement.control.borrow_mut();let mut port=Port{control:&mut control,native:Direction::Decode(native),body};port.work(1,size_of::<Reconstruction>())?;*slot=Some(Reconstruction::new());validate(source,database,slot.as_mut().unwrap(),&mut port)?;let owned=port.owned();drop(port);drop(control);settlement.finish_body(owned)
 }));match result{Ok(())=>Ok(()),Err(error)=>Err(settlement.refused(owner.native().owned_bytes(),error))}})();result.map(|()|store::io_schema::IoOutcome::clean(())).map_err(|error|store::io_schema::IoError::from_value_error(error.with_retained_progress(owner.progress())))
}
pub(super)fn validate_encoding(source:&StlSnapshot,dialect_input:&semio_framework_artifact_reference::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,owner:&mut store::NativeSnapshotEncodeOwner<'_,'_>)->store::io_schema::IoResult<()>{
 let result=(||{owner.native().checkpoint()?;control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,0,0)?;dialect(dialect_input)?;let before=owner.native().owned_bytes();let maximum=before.checked_add(control.allocation_remaining_bytes()).ok_or_else(||refusal(ValueRefusalKind::OwnershipLimit,"STL original SQL ceiling overflow"))?;let settlement=Settlement::new(control,before,SqliteSnapshotPhase::ReconstructSnapshot);let mut observer=|event:semio_framework_value::native_encoding::NativeEncodeProgress|settlement.observe(event.owned_bytes,event.completed,event.total);let result=owner.scoped_native(maximum,&mut observer,|owner|owner.receive::<Reconstruction,()>(|slot,native,body|{
  let mut control=settlement.control.borrow_mut();let mut port=Port{control:&mut control,native:Direction::Encode(native),body};port.work(1,size_of::<Reconstruction>())?;*slot=Some(Reconstruction::new());validate(source,database,slot.as_mut().unwrap(),&mut port)?;let owned=port.owned();drop(port);drop(control);settlement.finish_body(owned)
 }));match result{Ok(())=>Ok(()),Err(error)=>Err(settlement.refused(owner.native().owned_bytes(),error))}})();result.map(|()|store::io_schema::IoOutcome::clean(())).map_err(|error|store::io_schema::IoError::from_value_error(error.with_retained_progress(owner.progress())))
}
